"""Text-to-SQL harness: draft -> execute -> static checks -> evidence-backed repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _literals(sql):
    vals = []
    for m in LITERAL.finditer(sql or ""):
        v = m.group(1).replace("''", "'").strip()
        if v and len(v) >= 3 and not v.isdigit() and v.upper() not in ("T", "F"):
            if v not in vals:
                vals.append(v)
    return vals[:3]


def _tables_and_columns(schema):
    """Return list of (table, [columns]) parsed from CREATE TABLE statements."""
    out = []
    for m in re.finditer(r"CREATE\s+TABLE\s+[`\[\"]?(\w+)[`\]\"]?\s*\((.*?)\)\s*;", schema or "", re.S | re.I):
        table, body = m.group(1), m.group(2)
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            cm = re.match(r"[`\[\"]?(\w+)[`\]\"]?", p)
            if cm and cm.group(1).upper() not in (
                "PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT", "KEY"
            ):
                cols.append(cm.group(1))
        out.append((table, cols))
    return out


def _probe_values(env, schema, sql):
    """Sample real stored values resembling the string literals used in the draft."""
    lits = _literals(sql)
    if not lits:
        return ""
    tables = _tables_and_columns(schema)
    notes = []
    budget = 6
    for lit in lits:
        core = re.sub(r"[^A-Za-z0-9 ]", " ", lit).split()
        key = max(core, key=len) if core else lit
        key = key[:24]
        found = False
        for table, cols in tables:
            if found or budget <= 0:
                break
            for col in cols:
                if budget <= 0:
                    break
                probe = (
                    f'SELECT DISTINCT "{col}" FROM "{table}" '
                    f"WHERE LOWER(\"{col}\") LIKE '%{key.lower()}%' LIMIT 5"
                )
                try:
                    r = env.execute(probe, max_rows=5)
                except Exception:
                    continue
                budget -= 1
                if r.get("ok") and r.get("rows"):
                    vals = [str(row[0]) for row in r["rows"]]
                    notes.append(
                        f"Literal '{lit}' does not match exactly. Values containing '{key}' "
                        f"in {table}.{col}: {vals}"
                    )
                    found = True
                    break
    return "\n".join(notes)


# ---------------- static semantic checks ----------------

_KW = set("""select from where and or not exists in as on join inner left right full outer
cross union all distinct group by order having limit offset case when then else end asc desc
is null like between count sum avg min max cast coalesce ifnull substr lower upper length
abs round true false natural using with recursive except intersect values over partition
row_number rank dense_rank date strftime julianday instr replace trim ltrim rtrim int integer
real text blob numeric primary foreign key references default check unique constraint index
view table create insert update delete set into escape glob collate nocase""".split())


def _mask_strings(s):
    return re.sub(r"'(?:[^']|'')*'", lambda m: " " * len(m.group(0)), s)


def _clean(s):
    s = _mask_strings(s)
    s = re.sub(r"--[^\n]*", " ", s)
    s = re.sub(r"/\*.*?\*/", " ", s, flags=re.S)
    return s


def _match_paren(s, i):
    depth = 0
    for j in range(i, len(s)):
        if s[j] == "(":
            depth += 1
        elif s[j] == ")":
            depth -= 1
            if depth == 0:
                return j
    return -1


def _find_subqueries(clean):
    """Yield (start, end) spans of parenthesized SELECT subqueries."""
    spans = []
    for m in re.finditer(r"\(\s*select\b", clean, re.I):
        i = m.start()
        j = _match_paren(clean, i)
        if j > i:
            spans.append((i, j))
    return spans


def _refs(body):
    """FROM/JOIN table references as (name, alias_or_None); skips subquery sources."""
    out = []
    pat = re.compile(r"\b(?:from|join)\s+([`\[\"]?\w+[`\]\"]?)(?:\s+(?:as\s+)?([`\[\"]?\w+[`\]\"]?))?", re.I)
    for m in pat.finditer(body):
        name = m.group(1).strip('`[]"')
        alias = (m.group(2) or "").strip('`[]"') or None
        if alias and alias.lower() in _KW:
            alias = None
        out.append((name, alias))
    return out


def _static_warnings(sql, schema):
    """Detect silently-wrong SQL patterns that still execute successfully."""
    warns = []
    clean = _clean(sql)
    tables = {t.lower(): {c.lower() for c in cols} for t, cols in _tables_and_columns(schema)}
    spans = _find_subqueries(clean)
    for i, j in spans:
        inner = clean[i + 1:j]
        outer = clean[:i] + " " + clean[j + 1:]
        inner_refs = _refs(inner)
        outer_refs = _refs(outer)
        if not inner_refs or not outer_refs:
            continue
        inner_names = set()
        for n, a in inner_refs:
            inner_names.add(n.lower())
            if a:
                inner_names.add(a.lower())
        # Outer scope: drop anything shadowed by the inner FROM (SQLite resolves inner first).
        outer_eff = {}
        for n, a in outer_refs:
            key = (a or n).lower()
            if key in inner_names:
                continue
            cols = tables.get(n.lower(), set())
            outer_eff[key] = cols
        if not outer_eff:
            continue
        bad = set()
        for m in re.finditer(r"(?<![\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)", inner):
            q, c = m.group(1).lower(), m.group(2).lower()
            if q in inner_names:
                continue
            if q in outer_eff and (not outer_eff[q] or c in outer_eff[q]):
                bad.add(f"{m.group(1)}.{m.group(2)}")
        if bad:
            refs = ", ".join(sorted(bad))
            outer_aliases = ", ".join(sorted(outer_eff))
            warns.append(
                f"Inside the subquery, the reference(s) {refs} do NOT point to the outer query: "
                f"the subquery's own FROM tables shadow those names, so SQLite resolves them to "
                f"the INNER table (the condition degenerates into a self-comparison and the "
                f"filter becomes meaningless). Give the OUTER table an alias (e.g. FROM <table> AS O) "
                f"and correlate with O.<column>. Outer-scope names available: {outer_aliases}."
            )
    return warns


def _result_note(res):
    if not res.get("ok"):
        return f"ERROR: {res.get('error')}"
    if res.get("n_rows", 0) == 0:
        return "The query executed but returned ZERO rows."
    return None


def _sample_note(res):
    if not res.get("ok") or not res.get("rows"):
        return ""
    cols = res.get("columns") or []
    rows = res["rows"][:3]
    return (
        f"It returned {res.get('n_rows')} rows x {len(cols)} columns "
        f"(columns: {cols}). First rows: {rows}. "
        "Double-check this actually answers the question: right table's columns selected, "
        "right filter column, exact column set requested (no extras, none missing)."
    )


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += f"\n\nColumn descriptions:\n{desc.strip()[:2000]}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    try:
        res = env.execute(sql, max_rows=20)
    except Exception as e:
        res = {"ok": False, "error": str(e), "rows": [], "n_rows": 0}

    note = _result_note(res)
    try:
        warnings = _static_warnings(sql, schema)
    except Exception:
        warnings = []

    if note is None and not warnings:
        return {"sql": sql}

    # Draft errored, came back empty, or contains a detected semantic bug:
    # gather evidence and ask for one repair.
    evidence = ""
    try:
        evidence = _probe_values(env, schema, sql)
    except Exception:
        evidence = ""

    repair = f"Your draft query:\n```sql\n{sql}\n```\n"
    if note:
        repair += note + "\n"
    else:
        repair += _sample_note(res) + "\n"
    if warnings:
        repair += "\nDetected problems (the query runs but is semantically wrong):\n"
        for w in warnings:
            repair += f"- {w}\n"
    if evidence:
        repair += f"\nActual stored values found in the database:\n{evidence}\n"
    repair += (
        "\nDiagnose why the draft fails to answer the question and write a corrected query. "
        "Common causes:\n"
        "- Correlated subqueries: alias the outer table and reference it via that alias; an "
        "unaliased outer table whose name/columns also exist in the subquery's FROM silently "
        "compares the inner table to itself.\n"
        "- String literals must match stored data: values may differ in case, have trailing/leading "
        "spaces, or be embedded in longer text. Prefer case-insensitive substring matching "
        "(LOWER(col) LIKE '%...%') using a distinctive keyword from the question rather than exact "
        "equality on long phrases.\n"
        "- The filter may be on the wrong column or wrong table (e.g. filtering a parent document's "
        "name when the quoted text lives in the child paragraph's text column); check which column "
        "actually stores the mentioned value.\n"
        "- Projection: select exactly the columns asked for. If the question asks for an entity's "
        "details/all information, select that entity table's columns; if the gold-style answer "
        "includes attributes of a joined table mentioned in the question, include them too.\n"
        "- NOT IN over a subquery whose column can contain NULL returns no rows; use NOT EXISTS or "
        "add WHERE col IS NOT NULL. For 'has no friends/relationships', remember the entity can "
        "appear on either side of the relation table.\n"
        "- Join keys may be mismatched (wrong id column or wrong direction).\n"
        "Verify your fix mentally against the schema, then return ONLY the corrected query in a "
        "single ```sql block."
    )
    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": repair})
    try:
        reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = {"ok": False}
    if res2.get("ok"):
        # If we repaired a running-but-buggy draft, only accept a fix that still runs
        # and no longer carries the detected bug.
        if note is None and warnings:
            try:
                w2 = _static_warnings(sql2, schema)
            except Exception:
                w2 = []
            if w2:
                return {"sql": sql}
        return {"sql": sql2}
    return {"sql": sql}

